<?php
 namespace Pterodactyl\Services\Dezerx\Security; use Throwable; use Pterodactyl\Models\User; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Cache; use Pterodactyl\Models\Dezerx\AccountIp; use Pterodactyl\Services\Dezerx\Addons; class Security { private const CACHE_SECONDS = 86400; private const TIMEOUT = 5; public const VPN = 'vpn'; public const HOSTING = 'hosting'; public const DUPLICATE = 'duplicate'; public static function config(): array { return Addons::get(Addons::SECURITY); } public static function enabled(): bool { return (bool) (self::config()['enabled'] ?? false); } private static function flag(string $key): bool { return trim((string) (self::config()[$key] ?? '')) === '1'; } public static function key(): string { return trim((string) (self::config()['proxycheck_key'] ?? '')); } public static function allowed(): array { $raw = (string) (self::config()['ip_allowlist'] ?? ''); $out = []; foreach (preg_split('/[,\s]+/', $raw) ?: [] as $entry) { $ip = trim($entry); if ($ip !== '' && !in_array($ip, $out, true)) { $out[] = $ip; } } return $out; } public static function allowlisted(string $ip): bool { return in_array($ip, self::allowed(), true); } public static function refusal(string $ip, ?int $except = null): ?string { if (!self::enabled() || !self::public($ip) || self::allowlisted($ip)) { return null; } if (self::flag('duplicate_ip') && self::duplicate($ip, $except)) { return self::DUPLICATE; } if (!self::flag('block_vpn') && !self::flag('block_hosting')) { return null; } $answer = self::proxycheck($ip); if ($answer === null) { return null; } $type = mb_strtolower((string) ($answer['type'] ?? '')); $proxy = mb_strtolower((string) ($answer['proxy'] ?? 'no')) === 'yes'; if (self::flag('block_hosting') && $type === 'hosting') { return self::HOSTING; } if (self::flag('block_vpn') && $proxy && $type !== 'hosting') { return self::VPN; } return null; } public static function message(string $reason): string { return match ($reason) { self::DUPLICATE => 'An account has already been made from this connection. If it is yours, sign in to it instead.', self::HOSTING => 'Accounts cannot be made from a hosting or datacentre connection. Try again from your home connection.', default => 'Accounts cannot be made through a VPN or proxy. Turn it off and try again.', }; } public static function duplicate(string $ip, ?int $except = null): bool { return AccountIp::query() ->where('ip', $ip) ->when($except !== null, fn ($query) => $query->where('user_id', '!=', $except)) ->exists(); } public static function remember(User $user, ?string $ip, bool $registered = false): void { $ip = trim((string) $ip); if ($ip === '' || !self::public($ip)) { return; } try { $row = AccountIp::query()->firstOrNew(['user_id' => $user->id, 'ip' => $ip]); $row->registered = $row->registered || $registered; $row->save(); } catch (Throwable) { } } public static function proxycheck(string $ip): ?array { return Cache::remember('dezerx:security:' . $ip, self::CACHE_SECONDS, function () use ($ip) { try { $response = Http::acceptJson() ->timeout(self::TIMEOUT) ->get('https://proxycheck.io/v2/' . rawurlencode($ip), array_filter([ 'key' => self::key(), 'vpn' => '1', 'asn' => '0', 'risk' => '0', ])); if (!$response->successful()) { return null; } $body = (array) $response->json(); if (($body['status'] ?? '') !== 'ok' || !is_array($body[$ip] ?? null)) { return null; } return $body[$ip]; } catch (Throwable) { return null; } }); } public static function forget(string $ip): void { Cache::forget('dezerx:security:' . $ip); } public static function public(string $ip): bool { return filter_var( $ip, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE, ) !== false; } } 